VkResult cvkConvertCooperativeVectorMatrixNV(VkDevice                          device,
                                             const void*                       pNext,
                                             size_t                            srcSize,
                                             VkDeviceOrHostAddressConstKHR     srcData,
                                             size_t*                           pDstSize,
                                             VkDeviceOrHostAddressKHR          dstData,
                                             VkComponentTypeKHR                srcComponentType,
                                             VkComponentTypeKHR                dstComponentType,
                                             uint32_t                          numRows,
                                             uint32_t                          numColumns,
                                             VkCooperativeVectorMatrixLayoutNV srcLayout,
                                             size_t                            srcStride,
                                             VkCooperativeVectorMatrixLayoutNV dstLayout,
                                             size_t                            dstStride)
{
    VkConvertCooperativeVectorMatrixInfoNV info;
    VkResult                               result;

    info = (VkConvertCooperativeVectorMatrixInfoNV)
    {
        .sType            = VK_STRUCTURE_TYPE_CONVERT_COOPERATIVE_VECTOR_MATRIX_INFO_NV,
        .pNext            = pNext,
        .srcSize          = srcSize,
        .srcData          = srcData,
        .pDstSize         = pDstSize,
        .dstData          = dstData,
        .srcComponentType = srcComponentType,
        .dstComponentType = dstComponentType,
        .numRows          = numRows,
        .numColumns       = numColumns,
        .srcLayout        = srcLayout,
        .srcStride        = srcStride,
        .dstLayout        = dstLayout,
        .dstStride        = dstStride
    };

    result = vkConvertCooperativeVectorMatrixNV(device, &info);
    CVK_ASSERT((0 <= result));

    return result;
}
