VkBool32 cvkGetPhysicalDeviceExternalImageImportSupport(VkPhysicalDevice                   physicalDevice,
                                                        VkExternalMemoryHandleTypeFlagBits handleType,
                                                        VkFormat                           format,
                                                        VkImageType                        type,
                                                        VkImageTiling                      tiling,
                                                        VkImageUsageFlags                  usage,
                                                        VkImageCreateFlags                 flags,
                                                        const void*                        pImageFormatInfoNext,
                                                        VkBool32*                          pDedicatedOnly)
{
    VkPhysicalDeviceExternalImageFormatInfo external_image_format_info;
    VkExternalImageFormatProperties         external_image_format_properties;
    VkResult                                result;

    cvkInitPhysicalDeviceExternalImageFormatInfo(&external_image_format_info, pImageFormatInfoNext, handleType);

    result = cvkGetPhysicalDeviceExternalImageFormatProperties(physicalDevice, &external_image_format_info, format, type, tiling, usage, flags, NULL, &external_image_format_properties);

    (*pDedicatedOnly) =
        ((VK_SUCCESS == result) && (external_image_format_properties.externalMemoryProperties.externalMemoryFeatures & (VkExternalMemoryFeatureFlags)VK_EXTERNAL_MEMORY_FEATURE_DEDICATED_ONLY_BIT))
            ? VK_TRUE
            : VK_FALSE;

    return ((VK_SUCCESS == result) && (external_image_format_properties.externalMemoryProperties.externalMemoryFeatures & (VkExternalMemoryFeatureFlags)VK_EXTERNAL_MEMORY_FEATURE_IMPORTABLE_BIT))
               ? VK_TRUE
               : VK_FALSE;
}
VkBool32 cvkGetPhysicalDeviceExternalImageExportSupport(VkPhysicalDevice                   physicalDevice,
                                                        VkExternalMemoryHandleTypeFlagBits handleType,
                                                        VkFormat                           format,
                                                        VkImageType                        type,
                                                        VkImageTiling                      tiling,
                                                        VkImageUsageFlags                  usage,
                                                        VkImageCreateFlags                 flags,
                                                        const void*                        pImageFormatInfoNext,
                                                        VkBool32*                          pDedicatedOnly)
{
    VkPhysicalDeviceExternalImageFormatInfo external_image_format_info;
    VkExternalImageFormatProperties         external_image_format_properties;
    VkResult                                result;

    cvkInitPhysicalDeviceExternalImageFormatInfo(&external_image_format_info, pImageFormatInfoNext, handleType);

    result = cvkGetPhysicalDeviceExternalImageFormatProperties(physicalDevice, &external_image_format_info, format, type, tiling, usage, flags, NULL, &external_image_format_properties);

    (*pDedicatedOnly) =
        ((VK_SUCCESS == result) && (external_image_format_properties.externalMemoryProperties.externalMemoryFeatures & (VkExternalMemoryFeatureFlags)VK_EXTERNAL_MEMORY_FEATURE_DEDICATED_ONLY_BIT))
            ? VK_TRUE
            : VK_FALSE;

    return ((VK_SUCCESS == result) && (external_image_format_properties.externalMemoryProperties.externalMemoryFeatures & (VkExternalMemoryFeatureFlags)VK_EXTERNAL_MEMORY_FEATURE_EXPORTABLE_BIT))
               ? VK_TRUE
               : VK_FALSE;
}
void cvkAllocateImageMemory(VkPhysicalDevice             physicalDevice,
                            VkDevice                     device,
                            VkImage                      image,
                            VkMemoryPropertyFlags        requiredProperties,
                            const void*                  pMemoryNext,
                            const VkAllocationCallbacks* pAllocator,
                            VkDeviceMemory*              pMemory)
{
    VkMemoryRequirements memory_requirements;
    uint32_t             memory_type_index;

    cvkGetImageMemoryRequirements(device, image, &memory_requirements);

    memory_type_index = cvkGetPhysicalDeviceCompatibleMemoryTypeIndex(physicalDevice, memory_requirements.memoryTypeBits, requiredProperties);
    CVK_ASSERT(VK_INVALID != memory_type_index);

    cvkAllocateMemory(device, pMemoryNext, memory_requirements.size, memory_type_index, pAllocator, pMemory);
}
void cvkAllocateBufferMemory(VkPhysicalDevice             physicalDevice,
                             VkDevice                     device,
                             VkBuffer                     buffer,
                             VkMemoryPropertyFlags        requiredProperties,
                             const void*                  pMemoryNext,
                             const VkAllocationCallbacks* pAllocator,
                             VkDeviceMemory*              pMemory)
{
    VkMemoryRequirements memory_requirements;
    uint32_t             memory_type_index;

    cvkGetBufferMemoryRequirements(device, buffer, &memory_requirements);

    memory_type_index = cvkGetPhysicalDeviceCompatibleMemoryTypeIndex(physicalDevice, memory_requirements.memoryTypeBits, requiredProperties);
    CVK_ASSERT(VK_INVALID != memory_type_index);

    cvkAllocateMemory(device, pMemoryNext, memory_requirements.size, memory_type_index, pAllocator, pMemory);
}
void cvkSetupImage(VkPhysicalDevice             physicalDevice,
                   VkDevice                     device,
                   const void*                  pImageNext,
                   VkImageCreateFlags           flags,
                   VkImageType                  imageType,
                   VkFormat                     format,
                   VkExtent3D                   extent,
                   uint32_t                     mipLevels,
                   uint32_t                     arrayLayers,
                   VkSampleCountFlagBits        samples,
                   VkImageTiling                tiling,
                   VkImageUsageFlags            usage,
                   VkSharingMode                sharingMode,
                   uint32_t                     queueFamilyIndexCount,
                   const uint32_t*              pQueueFamilyIndices,
                   VkImageLayout                initialLayout,
                   VkMemoryPropertyFlags        requiredProperties,
                   const void*                  pMemoryNext,
                   const VkAllocationCallbacks* pAllocator,
                   VkImage*                     pImage,
                   VkDeviceMemory*              pMemory)
{
    cvkCreateImage(device,
                   pImageNext,
                   flags,
                   imageType,
                   format,
                   extent,
                   mipLevels,
                   arrayLayers,
                   samples,
                   tiling,
                   usage,
                   sharingMode,
                   queueFamilyIndexCount,
                   pQueueFamilyIndices,
                   initialLayout,
                   pAllocator,
                   pImage);
    cvkAllocateImageMemory(physicalDevice, device, (*pImage), requiredProperties, pMemoryNext, pAllocator, pMemory);
    cvkBindImageMemory(device, (*pImage), (*pMemory), VK_NO_OFFSET);
}
void cvkSetupBuffer(VkPhysicalDevice             physicalDevice,
                    VkDevice                     device,
                    const void*                  pBufferNext,
                    VkBufferCreateFlags          flags,
                    VkDeviceSize                 size,
                    VkBufferUsageFlags           usage,
                    VkSharingMode                sharingMode,
                    uint32_t                     queueFamilyIndexCount,
                    const uint32_t*              pQueueFamilyIndices,
                    VkMemoryPropertyFlags        requiredProperties,
                    const void*                  pMemoryNext,
                    const VkAllocationCallbacks* pAllocator,
                    VkBuffer*                    pBuffer,
                    VkDeviceMemory*              pMemory)
{
    cvkCreateBuffer(device, pBufferNext, flags, size, usage, sharingMode, queueFamilyIndexCount, pQueueFamilyIndices, pAllocator, pBuffer);
    cvkAllocateBufferMemory(physicalDevice, device, (*pBuffer), requiredProperties, pMemoryNext, pAllocator, pMemory);
    cvkBindBufferMemory(device, (*pBuffer), (*pMemory), VK_NO_OFFSET);
}
void cvkSetupDeviceQueue(VkPhysicalDevice                physicalDevice,
                         uint32_t                        queueFamilyIndex,
                         const void*                     pDeviceNext,
                         VkDeviceCreateFlags             flags,
                         uint32_t                        enabledLayerCount,
                         const char* const*              ppEnabledLayerNames,
                         uint32_t                        enabledExtensionCount,
                         const char* const*              ppEnabledExtensionNames,
                         const VkPhysicalDeviceFeatures* pEnabledFeatures,
                         const void*                     pQueueNext,
                         VkDeviceQueueCreateFlags        queueFlags,
                         float                           queuePriority,
                         const VkAllocationCallbacks*    pAllocator,
                         VkDevice*                       pDevice,
                         VkQueue*                        pQueue)
{
    VkBool32                extensions_supported;
    VkDeviceQueueCreateInfo device_queue_create_info;

    extensions_supported = cvkGetPhysicalDeviceExtensionSupport(physicalDevice, NULL, enabledExtensionCount, ppEnabledExtensionNames);
    CVK_ASSERT(extensions_supported);

    cvkInitDeviceQueueCreateInfo(&device_queue_create_info, pQueueNext, queueFlags, queueFamilyIndex, 1, &queuePriority);
    cvkCreateDevice(physicalDevice,
                    pDeviceNext,
                    flags,
                    1,
                    &device_queue_create_info,
                    enabledLayerCount,
                    ppEnabledLayerNames,
                    enabledExtensionCount,
                    ppEnabledExtensionNames,
                    pEnabledFeatures,
                    pAllocator,
                    pDevice);
    cvkGetDeviceQueue((*pDevice), queueFamilyIndex, 0, pQueue);
}
